sys_declarative_action_assignment.client_script:
function onClick() {

    getMessages(["Department", "Location", "External", "Add external user", "not a valid phone number", "Invalid email address", "First name", "Last name", "Email address", "Phone number", "Preferred language", "Select language", "English", "French"], onCreate);


    function onCreate(tMsgs) {

        var strTitle = tMsgs["Add external user"];
        var strValidPhone = tMsgs["not a valid phone number"];
        var strValidEmail = tMsgs["Invalid email address"];
        var regexemail = /^[A-Za-z0-9+_.-]+@(.+)$/;
        var regphone = /^[(]?(\d{3})[)]?[-|\s]?(\d{3})[-|\s]?(\d{4})$/;

        var fields = [{
                type: 'string',
                name: 'first_name',
                label: tMsgs['First name'],
                mandatory: true
            },
            {
                type: 'string',
                name: 'last_name',
                label: tMsgs['Last name'],
                mandatory: true
            },

            {
                type: 'string',
                name: 'email',
                label: tMsgs['Email address'],
                mandatory: false
            },
            {
                type: 'string',
                name: 'phone_number',
                label: tMsgs['Phone number'],
                mandatory: false
            },

            {
                type: 'reference',
                name: 'u_affected_department',
                label: tMsgs['Department'],
                mandatory: false,
                reference: 'cmn_department',
                referringTable: 'incident',
                referringRecordId: g_form.getUniqueValue(),
               value:g_scratchpad.externalDepartment, 
                displayValue: "External"


            },
            {
                type: 'reference',
                name: 'u_affected_location',
                label: tMsgs['Location'],
                mandatory: false,
                reference: 'cmn_location',
                referringTable: 'incident',
                referringRecordId: g_form.getUniqueValue(),
                value: g_scratchpad.externalLocation,
                displayValue: "External"

            },


            {
                type: 'choice',
                name: 'preferred_language',
                label: tMsgs['Preferred language'],
                value: tMsgs['Select language'],
                choices: [{
                        displayValue: tMsgs['English'],
                        value: 'en',
                        selected: true
                    },
                    {
                        displayValue: tMsgs['French'],
                        value: 'fq'
                    }
                ],
                mandatory: false
            }
        ]

        g_modal.showFields({
            title: strTitle,
            fields: fields,
            size: 'xl',
            height:'900'

        }).then(function(fieldValues) {



            var validEmail = true;
			if(fieldValues.updatedFields[2].value) {
				validEmail = validateData(fieldValues.updatedFields[2].value, regexemail, strValidEmail);
			}
            var validPhone = (fieldValues.updatedFields[3].value == "" || fieldValues.updatedFields[3].value === undefined) ? true : validateData(fieldValues.updatedFields[3].value, regphone, strValidPhone);

            if (validEmail && validPhone) {

                var strData = JSON.stringify(fieldValues.updatedFields);

                var ga = new GlideAjax("global.HoCITSMCommonAjaxUtils");
                ga.addParam("sysparm_name", "createExternalUser");
                ga.addParam("sysparm_data", strData);
                ga.getXMLAnswer(setAnswer);
            }

        }); //then



        function validateData(itemValue, regExpression, strMsg) {

            if (itemValue && !regExpression.test(itemValue)) {
                alert(strMsg);
                return false;

            }
            return true;
        }


        function setAnswer(response) {

            if (response.length < 37 && response.length > 0) {

                g_form.setValue('caller_id', response);

            }
            if (response.length > 36) {
                g_form.clearValue('caller_id');
                g_form.addErrorMessage(response);
            }
        }


    }



}
